import {categories,definitions,icon,streamTypes,linkTypes} from './components.js';
import {Store,clone,uid,createNode,createStream,blankDiagram,demoDiagram,transposeOrientation,blankProject,asProject} from './model.js';
import {esc,renderDiagram,bounds,port,roundedPath,palettes,edgePoints} from './canvas.js';
import {validate,modelErrors,projectErrors} from './validation.js';
import {exportFile,fromXML,toXML} from './io.js';
import {setupProjectUI} from './project-ui.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let recovered=false,loadFailure=false,legacy=null,initial=blankProject();
try{const raw=localStorage.getItem('tengwar.project.v2');if(raw){const p=JSON.parse(raw);if(!projectErrors(p).length){initial=p;recovered=true;}else loadFailure=true;}const old=localStorage.getItem('tengwar.workspace.v1');if(old){const d=JSON.parse(old);if(!modelErrors(d).length)legacy=d;}}catch{loadFailure=true;}
const store=new Store(initial),selected=new Set(),viewStates=new Map();let projectUI=null,renderedFlowId=null;
let mode='design',tool='select',camera={x:0,y:0,zoom:1},gesture=null,connecting=null,space=false,clipboard=null,validationOpen=false,exportFormat='png',toastTimer,activePreview=null;
const canvas=$('#canvas'),viewport=$('#viewport'),overlay=$('#overlay');
if(innerWidth<=800)document.body.classList.add('library-hidden','inspector-hidden');
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);});root.querySelectorAll('[data-leading]').forEach(el=>{if(!el.querySelector(':scope > svg'))el.insertAdjacentHTML('afterbegin',icon(el.dataset.leading));});}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800);$('#status-message').textContent=message;setTimeout(()=>{if($('#status-message').textContent===message)$('#status-message').textContent=mode==='view'?'Read-only':'Ready';},4000);}
function canEdit(){return mode==='design';}
function viewTransform(){viewport.setAttribute('transform',`translate(${camera.x},${camera.y}) scale(${camera.zoom})`);overlay.setAttribute('transform',viewport.getAttribute('transform'));const d=store.diagram;canvas.style.backgroundImage=d.settings.grid?'radial-gradient(circle, var(--dot) 1px, transparent 1.2px)':'none';canvas.style.backgroundSize=`${d.settings.gridSize*camera.zoom}px ${d.settings.gridSize*camera.zoom}px`;canvas.style.backgroundPosition=`${camera.x}px ${camera.y}px`;$('#zoom-value').textContent=Math.round(camera.zoom*100)+'%';}
function renderCanvas(d=store.diagram){viewport.innerHTML=renderDiagram(d,selected,true);viewTransform();$('#empty-state').hidden=d.nodes.length>0;}
function fit(){const rect=canvas.getBoundingClientRect();if(!store.diagram.nodes.length){camera={x:80,y:100,zoom:1};viewTransform();return;}const b=bounds(store.diagram);const availW=Math.max(160,rect.width-80),availH=Math.max(100,rect.height-175);camera.zoom=Math.min(1.15,availW/b.width,availH/b.height);camera.zoom=Math.max(.1,camera.zoom);camera.x=50+(availW-b.width*camera.zoom)/2-b.x*camera.zoom;camera.y=108+(availH-b.height*camera.zoom)/2-b.y*camera.zoom;viewTransform();}
function zoom(factor,point){const r=canvas.getBoundingClientRect(),p=point||{x:r.width/2,y:r.height/2};const next=Math.min(3,Math.max(.1,camera.zoom*factor));const ratio=next/camera.zoom;camera.x=p.x-(p.x-camera.x)*ratio;camera.y=p.y-(p.y-camera.y)*ratio;camera.zoom=next;viewTransform();}
function world(event){const r=canvas.getBoundingClientRect();return{x:(event.clientX-r.left-camera.x)/camera.zoom,y:(event.clientY-r.top-camera.y)/camera.zoom};}
function snap(v){return store.diagram.settings.snap?Math.round(v/store.diagram.settings.gridSize)*store.diagram.settings.gridSize:v;}
function select(id,multi=false){if(!multi)selected.clear();if(id){if(multi&&selected.has(id))selected.delete(id);else selected.add(id);}renderCanvas();renderInspector();updateHeader();}
function focusElement(id){const n=store.diagram.nodes.find(n=>n.id===id),e=store.diagram.edges.find(e=>e.id===id);if(!n&&!e)return;select(id);const r=canvas.getBoundingClientRect();let b;if(n)b={x:n.x,y:n.y,width:n.width,height:n.height};else{const pts=edgePoints(e,store.diagram.nodes);b={x:Math.min(...pts.map(p=>p.x)),y:Math.min(...pts.map(p=>p.y)),width:Math.max(...pts.map(p=>p.x))-Math.min(...pts.map(p=>p.x)),height:Math.max(...pts.map(p=>p.y))-Math.min(...pts.map(p=>p.y))};}camera.zoom=Math.min(1.3,Math.max(.65,camera.zoom));camera.x=r.width/2-(b.x+b.width/2)*camera.zoom;camera.y=(validationOpen?r.height*.35:r.height*.5)-(b.y+b.height/2)*camera.zoom;viewTransform();}
function library(){const query=$('#component-search').value.toLowerCase();const opened=new Set($$('#component-list .category[open]').map(el=>el.dataset.category));const first=!$('#component-list').children.length;$('#component-list').innerHTML=Object.entries(categories).map(([category,labels],i)=>{const defs=labels.map(label=>Object.values(definitions).find(d=>d.label===label)).filter(d=>(d.label+' '+d.description+' '+category).toLowerCase().includes(query));if(!defs.length)return '';return `<details class="category" data-category="${esc(category)}" ${query||opened.has(category)||first&&i<2?'open':''}><summary>${icon('chevron')} ${esc(category)} <span class="category-count">${defs.length.toString().padStart(2,'0')}</span></summary><div class="component-grid">${defs.map(d=>`<button class="component" draggable="${canEdit()}" data-component="${d.type}" title="${esc(d.description)}" ${canEdit()?'':'disabled'}><span>${icon(d.type,22)}</span><span>${esc(d.label)}</span></button>`).join('')}</div></details>`;}).join('')||'<p class="no-results">No matching components.<br>Try “filter”, “sample” or “material”.</p>';}
function updateHeader(){const d=store.diagram;document.documentElement.dataset.theme=d.settings.theme;$('#project-title').textContent=store.project.name||'Untitled project';$('#canvas-title').textContent=d.name||'Untitled process';$('#revision').textContent='v'+(store.project.version||'1.0');$('#counts').textContent=`${d.nodes.length} components · ${d.edges.length} streams`;$('#selection-count').textContent=selected.size?`${selected.size} selected`:'';$('#canvas-mode').textContent=mode==='view'?'VIEW · READ ONLY':'DESIGN MODE';$('#undo').disabled=!canEdit()||!store.past.length;$('#redo').disabled=!canEdit()||!store.future.length;$('#grid-toggle').classList.toggle('active',d.settings.grid);$('#snap-toggle').textContent=d.settings.snap?'Snap on':'Snap off';$('#orientation').innerHTML=icon(d.settings.orientation)+' '+(d.settings.orientation==='horizontal'?'Horizontal flow':'Vertical flow');$('#orientation').disabled=!canEdit();$('#snap-toggle').disabled=!canEdit();$('#grid-toggle').disabled=!canEdit();$('#theme-toggle').innerHTML=icon(d.settings.theme==='light'?'moon':'sun');$('#theme-toggle').title=d.settings.theme==='light'?'Switch to dark mode':'Switch to light mode';$('#theme-toggle').setAttribute('aria-label',$('#theme-toggle').title);$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',b.dataset.mode===mode);});$$('[data-tool]').forEach(b=>{b.classList.toggle('active',b.dataset.tool===tool);b.disabled=b.dataset.tool==='connect'&&!canEdit();b.setAttribute('aria-pressed',b.dataset.tool===tool);});document.body.classList.toggle('view-mode',mode==='view');$('#saved-state').innerHTML=icon(store.autosaveOk?'check':'warning',14)+(store.autosaveOk?' Saved locally':' Autosave unavailable');$('#saved-state').title=store.autosaveOk?'Local browser recovery copy. Save XML to keep a portable project file.':'Browser storage is unavailable or full. Save XML to keep your work.';}
const section=(name,body,open=false)=>`<details class="inspector-section" data-section="${esc(name)}" ${open?'open':''}><summary>${esc(name)}${icon('chevron')}</summary><div class="section-body">${body}</div></details>`;
function field(label,key,value,kind='text',options=[],scope='property'){const readonly=!canEdit();const attrs=`data-field="${esc(key)}" data-scope="${scope}"`;return `<label class="field"><span>${esc(label)}</span>${kind==='textarea'?`<textarea ${attrs} ${readonly?'readonly':''}>${esc(value)}</textarea>`:kind==='select'?`<select ${attrs} ${readonly?'disabled':''}>${options.map(o=>{const val=typeof o==='object'?o.value:o,text=typeof o==='object'?o.label:o;return `<option value="${esc(val)}" ${String(value)===String(val)?'selected':''}>${esc(text)}</option>`;}).join('')}</select>`:`<input type="${kind}" ${attrs} value="${esc(value)}" ${readonly?'readonly':''} ${kind==='number'?'step="any"':''}>`}</label>`;}
function customProperties(obj,scope='additional'){const entries=Object.entries(obj||{});return `<p class="property-help">Add your own documented attributes, such as batch number, SOP or owner.</p>${entries.map(([k,v])=>`<div class="custom-property"><input aria-label="Property key" value="${esc(k)}" readonly><input aria-label="Value for ${esc(k)}" data-custom="${esc(k)}" data-custom-scope="${scope}" value="${esc(v)}" ${canEdit()?'':'readonly'}><button class="icon-button" data-remove-property="${esc(k)}" data-custom-scope="${scope}" aria-label="Remove ${esc(k)}" ${canEdit()?'':'disabled'}>${icon('close')}</button></div>`).join('')}${canEdit()?`<button class="button compact" data-action="add-property" data-custom-scope="${scope}">${icon('plus')}Add property</button>`:''}`;}
function connections(n){const d=store.diagram;const part=(label,arr)=>`<div class="field"><span>${label} <small>(${arr.length})</small></span>${arr.length?arr.map(e=>`<button class="stream-chip" data-focus="${esc(e.id)}">${esc(e.properties.streamId)}<span>${esc(e.properties.name)}</span>${icon('arrow')}</button>`).join(''):'<p class="property-help">No streams connected</p>'}</div>`;return part('Inlet streams',d.edges.filter(e=>e.destination===n.id))+part('Outlet streams',d.edges.filter(e=>e.source===n.id));}
function renderInspector(){
 const d=store.diagram,ids=[...selected],n=d.nodes.find(n=>n.id===ids[0]),e=d.edges.find(e=>e.id===ids[0]);let content='';const previous=$('#inspector-content').dataset.target;const target=store.diagram.id+':'+(ids.length===1?ids[0]:ids.length?'multi':'diagram');const opened=new Set($$('#inspector-content details[open]').map(el=>el.dataset.section));const scroll=$('#inspector-content').scrollTop;
 if(mode==='view')content+='<div class="mode-message">View mode · properties are read-only</div>';
 if(ids.length>1){content+=`<div class="selection-header"><span class="selection-icon">${icon('layers')}</span><div><h3>${ids.length} elements selected</h3><p>MULTIPLE SELECTION</p></div></div>`+section('Selection',`<p class="property-help">Drag any selected component to move the selection together.</p><div class="inspector-actions"><button class="button compact" data-action="duplicate" ${canEdit()?'':'disabled'}>${icon('copy')}Duplicate</button><button class="button compact danger" data-action="delete" ${canEdit()?'':'disabled'}>${icon('trash')}Delete</button></div>`,true);}
 else if(n){const def=definitions[n.type],p=n.properties;content+=`<div class="selection-header"><span class="selection-icon">${icon(n.type,24)}</span><div><h3>${esc(p.name||def.label)}</h3><p>${esc(def.category.toUpperCase())}</p></div></div>`;
 content+=section('General',field('Name','name',p.name)+field('Component type','type',n.type,'select',Object.values(definitions).map(d=>({value:d.type,label:d.label})),'node')+field('Description','description',p.description,'textarea'),true);
 content+=section('Process',field('Material','material',p.material)+`<div class="field-row">${field('Quantity','quantity',p.quantity)}${field('Unit','unit',p.unit)}</div>`+field('Phase','phase',p.phase)+field('Classification','classification',p.classification,'select',['',...streamTypes])+field('Condition / criteria','condition',p.condition),def.family==='material');
 if(['operation','equipment'].includes(def.family))content+=section('Equipment',field('Equipment ID','equipmentId',p.equipmentId)+field('Equipment type','equipmentType',p.equipmentType)+field('Capacity','capacity',p.capacity),true);
 content+=section('Connections',connections(n),true);
 content+=section('Quality',field('Test / analytical method','test',p.test)+field('Reference','reference',p.reference),def.family==='quality');
 content+=section('Documentation',field('Notes','notes',p.notes,'textarea')+field('Mandatory property keys','requiredFields',p.requiredFields)+`<p class="property-help">Comma-separated keys, e.g. equipmentId, reference. Checked during structural validation.</p>`,def.family==='documentation');
 content+=section('Appearance',field('Accent','accent',p.accent,'select',[{value:'default',label:'Default'},{value:'cobalt',label:'Cobalt'},{value:'teal',label:'Desaturated teal'},{value:'graphite',label:'Graphite'}])+`<div class="field-row">${field('X','x',n.x,'number',[],'node')}${field('Y','y',n.y,'number',[],'node')}</div><div class="field-row">${field('Width','width',n.width,'number',[],'node')}${field('Height','height',n.height,'number',[],'node')}</div>`);
 content+=section('Additional properties',customProperties(p.additional));
 content+=section('Actions',`<div class="inspector-actions"><button class="button compact" data-action="duplicate" ${canEdit()?'':'disabled'}>${icon('copy')}Duplicate</button><button class="button compact danger" data-action="delete" ${canEdit()?'':'disabled'}>${icon('trash')}Delete</button></div>`);
 }else if(e){const p=e.properties;content+=`<div class="selection-header"><span class="selection-icon">${icon('connect',24)}</span><div><h3>${esc(p.streamId||'Stream')}</h3><p>PROCESS STREAM</p></div></div>`;
 content+=section('General',field('Stream ID','streamId',p.streamId)+field('Name','name',p.name)+field('Type','type',p.type,'select',streamTypes)+field('Link style','linkType',p.linkType,'select',linkTypes),true);
 content+=section('Connections',field('Source','source',e.source,'select',d.nodes.filter(n=>definitions[n.type].ports.length).map(n=>({value:n.id,label:n.properties.name})),'edge')+field('Source port','sourcePort',e.sourcePort,'select',['left','right','top','bottom'],'edge')+field('Destination','destination',e.destination,'select',d.nodes.filter(n=>definitions[n.type].ports.length).map(n=>({value:n.id,label:n.properties.name})),'edge')+field('Destination port','destinationPort',e.destinationPort,'select',['left','right','top','bottom'],'edge'),true);
 content+=section('Process',field('Material','material',p.material)+field('Phase','phase',p.phase),true);
 content+=section('Documentation',field('Description','description',p.description,'textarea')+field('Notes','notes',p.notes,'textarea'));
 content+=section('Routing',field('Routing mode','routing',e.routing,'select',['auto','manual'],'edge')+field('Bend coordinate','routeOffset',e.routeOffset,'number',[],'edge')+'<p class="property-help">Drag the handle on a selected stream to adjust its orthogonal route, or edit this coordinate.</p>');
 content+=section('Additional properties',customProperties(p.additional));
 content+=section('Actions',`<button class="button compact danger" data-action="delete" ${canEdit()?'':'disabled'}>${icon('trash')}Delete stream</button>`);
 }else{content+=`<div class="selection-header"><span class="selection-icon">${icon('layers',24)}</span><div><h3>Flow Inspector</h3><p>PROCESS DOCUMENT</p></div></div>`;
 content+=section('General',field('Flow name','name',d.name,'text',[],'diagram')+field('Description','description',d.description,'textarea',[],'diagram')+field('Author (optional)','author',d.author,'text',[],'diagram')+field('Version','version',d.version,'text',[],'diagram'),true);
 content+=section('Canvas',field('Orientation','orientation',d.settings.orientation,'select',['horizontal','vertical'],'settings')+`<label class="toggle-field">Dot grid<input type="checkbox" data-field="grid" data-scope="settings" ${d.settings.grid?'checked':''} ${canEdit()?'':'disabled'}></label><label class="toggle-field">Snap to grid<input type="checkbox" data-field="snap" data-scope="settings" ${d.settings.snap?'checked':''} ${canEdit()?'':'disabled'}></label>`+field('Grid spacing (8–80)','gridSize',d.settings.gridSize,'number',[],'settings')+`<label class="toggle-field">Stream labels<input type="checkbox" data-field="showStreamLabels" data-scope="settings" ${d.settings.showStreamLabels?'checked':''} ${canEdit()?'':'disabled'}></label>`,true);
 content+=section('Components',`<div class="navigator-list">${d.nodes.map(n=>`<button class="stream-chip" data-focus="${esc(n.id)}">${esc(n.properties.name||definitions[n.type].label)}${icon('arrow')}</button>`).join('')||'<p class="property-help">Add a component from the library.</p>'}</div>`);
 content+=section('Metadata',customProperties(d.metadata,'metadata'));
 content+=section('Local workspace','<p class="property-help">This project is recovered in this browser. Save project downloads every flow together in one portable XML file.</p>');
 }
 $('#inspector-content').innerHTML=content;$('#inspector-content').dataset.target=target;
 if(previous===target){$$('#inspector-content details').forEach(el=>el.open=opened.has(el.dataset.section));$('#inspector-content').scrollTop=scroll;}
}
function renderValidation(){if(!validationOpen){$('#validation-panel').hidden=true;$('.validate-btn').classList.remove('active');return;}const v=validate(store.diagram);$('#validation-panel').hidden=false;$('.validate-btn').classList.add('active');$('#validation-badge').textContent=v.errors+v.warnings||'';$('#validation-panel').innerHTML=`<div class="validation-head"><h3>Structural validation</h3><div class="validation-stats"><span class="pass">✓ ${v.passes} checks passed</span><span class="warn">${v.warnings} warnings</span><span class="danger">${v.errors} errors</span></div><button class="icon-button" data-action="close-validation" aria-label="Close validation">${icon('close')}</button></div><p class="validation-note">Checks connectivity, identification and documentation. Chemical correctness and GMP compliance are outside this review.</p>${v.findings.length?v.findings.map(f=>`<button class="finding ${f.level}" ${f.id?`data-focus="${esc(f.id)}"`:''}>${icon(f.level==='information'?'info':'warning')}<span>${esc(f.message)}<small>${esc(f.check)} · ${f.level}</small></span></button>`).join(''):'<div class="validation-success">'+icon('check')+' All structural checks passed.</div>'}`;}
function render(){const changed=renderedFlowId!==store.diagram.id;if(changed){if(renderedFlowId)viewStates.set(renderedFlowId,{...camera});renderedFlowId=store.diagram.id;selected.clear();gesture=null;activePreview=null;cancelConnect();}selected.forEach(id=>{if(!store.diagram.nodes.some(n=>n.id===id)&&!store.diagram.edges.some(e=>e.id===id))selected.delete(id);});updateHeader();renderCanvas();renderInspector();renderValidation();projectUI?.renderTabs();if(changed)requestAnimationFrame(()=>{const saved=viewStates.get(store.diagram.id);if(saved){camera={...saved};viewTransform();}else fit();});}
store.addEventListener('change',render);
function setMode(next){if(next===mode)return;if(gesture){gesture=null;activePreview=null;renderCanvas();}tool='select';cancelConnect();mode=next;library();updateHeader();renderInspector();projectUI?.renderTabs();toast(mode==='view'?'View mode · editing locked':'Design mode');}
function setTool(next){if(next==='connect'&&!canEdit())return;cancelConnect();tool=next;canvas.style.cursor=next==='pan'?'grab':next==='connect'?'crosshair':'default';updateHeader();$('#connection-hint').hidden=next!=='connect';document.body.classList.toggle('connecting',next==='connect');}
function orientation(next){if(!canEdit()||next===store.diagram.settings.orientation)return;store.commit(d=>transposeOrientation(d,next));fit();toast(next==='vertical'?'Vertical flow · positions preserved':'Horizontal flow · positions preserved');}
function addComponent(type,point){if(!canEdit())return;const def=definitions[type];if(!def)return;if(store.diagram.nodes.length>=1000||store.project.diagrams.reduce((n,d)=>n+d.nodes.length,0)>=10000){toast('Limit reached: 1,000 components per flow or 10,000 per project.');return;}const r=canvas.getBoundingClientRect(),p=point||{x:(r.width/2-camera.x)/camera.zoom,y:(r.height/2-camera.y)/camera.zoom};const n=createNode(type,snap(p.x-def.width/2),snap(p.y-def.height/2));store.commit(d=>d.nodes.push(n));select(n.id);toast(def.label+' added');}
function cancelConnect(){connecting=null;overlay.innerHTML='';document.body.classList.toggle('connecting',tool==='connect');$('#connection-hint').hidden=tool!=='connect';}
function finishConnection(target){if(!connecting||!target||!canEdit())return false;if(store.diagram.edges.length>=3000||store.project.diagrams.reduce((n,d)=>n+d.edges.length,0)>=30000){toast('Stream limit reached');cancelConnect();return false;}const a=connecting;if(a.node===target.node&&a.side===target.side)return false;if(store.diagram.edges.some(e=>e.source===a.node&&e.destination===target.node&&e.sourcePort===a.side&&e.destinationPort===target.side)){toast('These ports are already connected');cancelConnect();return false;}const ids=new Set(store.diagram.edges.map(e=>e.properties.streamId));let next=1;while(ids.has('S-'+String(next).padStart(3,'0')))next++;const e=createStream(a.node,target.node,a.side,target.side,next);store.commit(d=>d.edges.push(e));cancelConnect();select(e.id);toast('Stream connected');return true;}
function nearestPort(event){const p=world(event);let best=null,dist=18/camera.zoom;for(const n of store.diagram.nodes)for(const side of definitions[n.type].ports){const q=port(n,side),v=Math.hypot(q.x-p.x,q.y-p.y);if(v<dist&&(!connecting||n.id!==connecting.node||side!==connecting.side)){best={node:n.id,side};dist=v;}}return best;}
function deleteSelection(){if(!canEdit()||!selected.size)return;const count=selected.size;store.commit(d=>{d.nodes=d.nodes.filter(n=>!selected.has(n.id));d.edges=d.edges.filter(e=>!selected.has(e.id)&&!selected.has(e.source)&&!selected.has(e.destination));});selected.clear();render();toast(`${count} element${count===1?'':'s'} deleted · Undo to restore`);}
function copy(){const d=store.diagram,nodes=d.nodes.filter(n=>selected.has(n.id));if(!nodes.length){toast('Select components to copy');return;}const ids=new Set(nodes.map(n=>n.id));clipboard=clone({nodes,edges:d.edges.filter(e=>ids.has(e.source)&&ids.has(e.destination))});toast(`${nodes.length} component${nodes.length===1?'':'s'} copied`);}
function paste(){if(!canEdit()||!clipboard)return;if(store.diagram.nodes.length+clipboard.nodes.length>1000||store.project.diagrams.reduce((n,d)=>n+d.nodes.length,0)+clipboard.nodes.length>10000||store.diagram.edges.length+clipboard.edges.length>3000||store.project.diagrams.reduce((n,d)=>n+d.edges.length,0)+clipboard.edges.length>30000){toast('The selection exceeds the flow or project limit');return;}const group=clone(clipboard),map=new Map(group.nodes.map(n=>[n.id,uid('n')]));const existingEq=new Set(store.diagram.nodes.map(n=>n.properties.equipmentId));for(const n of group.nodes){n.id=map.get(n.id);n.x+=40;n.y+=40;if(n.properties.equipmentId){const base=n.properties.equipmentId+'-copy';let id=base,i=2;while(existingEq.has(id))id=base+'-'+i++;n.properties.equipmentId=id;existingEq.add(id);}}const existingIds=new Set(store.diagram.edges.map(e=>e.properties.streamId));let i=1;for(const e of group.edges){e.id=uid('e');e.source=map.get(e.source);e.destination=map.get(e.destination);while(existingIds.has('S-'+String(i).padStart(3,'0')))i++;e.properties.streamId='S-'+String(i++).padStart(3,'0');if(e.routing==='manual')e.routeOffset+=40;}selected.clear();group.nodes.forEach(n=>selected.add(n.id));store.commit(d=>{d.nodes.push(...group.nodes);d.edges.push(...group.edges);});clipboard=clone(group);toast('Selection pasted');}
function modal(title,body,footer=''){const el=$('#modal');$('#modal-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!el.open)el.showModal();}
function exportModal(){exportFormat='png';const b=bounds(store.diagram);modal('Export diagram',`<p>PNG and SVG export the active flow. Project XML saves every tab together.</p><div class="export-options">${[['png','PNG','With background'],['png-transparent','PNG Transparent','Without background'],['svg','SVG','Vector diagram'],['xml','Project XML',`${store.project.diagrams.length} flows · complete project`]].map(([key,name,desc])=>`<button class="export-option ${key==='png'?'active':''}" data-export-format="${key}">${icon(key==='xml'?'save':'download')}<strong>${name}</strong><small>${desc}</small></button>`).join('')}</div><label class="field" id="scale-field"><span>Image resolution</span><select id="export-scale"><option value="1">1× · Standard</option><option value="2" selected>2× · High resolution</option><option value="3">3× · Print</option></select></label><div class="export-dimensions" id="export-dimensions">${Math.ceil(b.width*2)} × ${Math.ceil(b.height*2)} px · ${store.diagram.settings.theme} theme</div>`,`<button class="button" data-action="close-modal">Cancel</button><button class="button primary" id="download-export" data-action="download-export">${icon('download')}Export diagram</button>`);}
function openError(message){modal('Unable to open diagram',`<p>The current workspace has been preserved.</p><div class="error-details">${esc(message)}</div>`,`<button class="button primary" data-action="close-modal">Close</button>`);}

function showMenu(x,y,diagram=false){const menu=$('#context-menu');menu.innerHTML=diagram?`<button data-action="new">${icon('plus')}New flow</button><button data-action="new-project">${icon('folder')}New project</button><button data-action="demo">${icon('layers')}Load example flow</button><hr><button data-action="save">${icon('save')}Save XML</button><button data-action="help">${icon('help')}Shortcuts & help</button>`:`<button data-action="copy">${icon('copy')}Copy <kbd>Ctrl C</kbd></button><button data-action="paste" ${canEdit()&&clipboard?'':'disabled'}>${icon('copy')}Paste <kbd>Ctrl V</kbd></button><button data-action="duplicate" ${canEdit()?'':'disabled'}>${icon('copy')}Duplicate <kbd>Ctrl D</kbd></button><hr><button class="danger" data-action="delete" ${canEdit()?'':'disabled'}>${icon('trash')}Delete <kbd>Del</kbd></button>`;menu.hidden=false;menu.style.left=Math.min(x,innerWidth-215)+'px';menu.style.top=Math.min(y,innerHeight-menu.offsetHeight-10)+'px';menu.querySelector('button:not(:disabled)')?.focus();}
const actions={library(){document.body.classList.toggle('library-hidden');if(innerWidth<=800&&!document.body.classList.contains('library-hidden'))document.body.classList.add('inspector-hidden');},inspector(){document.body.classList.toggle('inspector-hidden');if(innerWidth<=800&&!document.body.classList.contains('inspector-hidden'))document.body.classList.add('library-hidden');},diagram(){select(null);document.body.classList.remove('inspector-hidden');if(innerWidth<=800)document.body.classList.add('library-hidden');},theme(){store.commit(d=>d.settings.theme=d.settings.theme==='light'?'dark':'light');},open(){$('#file-input').click();},save(){exportFile(store.project,'xml').then(()=>toast(`Project exported · ${store.project.diagrams.length} flows in one XML`)).catch(e=>toast(e.message));},export:exportModal,undo(){if(canEdit()&&store.undo())toast('Undo');},redo(){if(canEdit()&&store.redo())toast('Redo');},grid(){if(canEdit())store.commit(d=>d.settings.grid=!d.settings.grid);},snap(){if(canEdit())store.commit(d=>d.settings.snap=!d.settings.snap);},orientation(){orientation(store.diagram.settings.orientation==='horizontal'?'vertical':'horizontal');},validate(){validationOpen=!validationOpen;renderValidation();},'close-validation'(){validationOpen=false;renderValidation();},fit,'zoom-in'(){zoom(1.2);},'zoom-out'(){zoom(1/1.2);},'reset-zoom'(){zoom(1/camera.zoom);},copy,paste,duplicate(){if(canEdit()){copy();paste();}},delete:deleteSelection,'close-modal'(){$('#modal').close();},more(event){const r=event?.currentTarget?.getBoundingClientRect?.()||$('#inspector').getBoundingClientRect();showMenu(r.right-210,r.bottom-210,true);},help(){modal('Working with Tengwar',`<p>Add components from the library. Drag between the small ports to create streams. Click a stream to edit its properties; drag its handle to adjust the route.</p>${[['Select tool','V'],['Pan tool / temporary pan','H / Space'],['Connect tool','C'],['Fit diagram','F'],['Multi-select','Shift + click'],['Box selection','Drag empty canvas'],['Copy / paste / duplicate','Ctrl C / V / D'],['Undo / redo','Ctrl Z / Shift Z'],['Move selected components','Arrow keys'],['Save XML','Ctrl S'],['Delete selection','Delete'],['Cancel connection / selection','Esc']].map(([a,b])=>`<div class="shortcut"><span>${a}</span><kbd>${b}</kbd></div>`).join('')}<p>View mode locks editing. Save project downloads one XML containing every flow. Use the tabs to switch flows; double-click a tab to rename it. The example loads in an additional tab. PNG and SVG export the active flow. Local autosave is limited to this browser.</p>`);},async 'download-export'(){const button=$('#download-export');button.disabled=true;button.textContent='Preparing export…';try{await exportFile(exportFormat==='xml'?store.project:store.diagram,exportFormat,Number($('#export-scale').value));$('#modal').close();toast('Diagram exported');}catch(e){toast(e.message);button.disabled=false;button.textContent='Export diagram';}}};
document.addEventListener('click',event=>{
 const action=event.target.closest('[data-action]');if(action&&!action.disabled){$('#context-menu').hidden=true;if(action.dataset.action==='add-property'){const scope=action.dataset.customScope;modal('Add property',`<label class="field"><span>Property name</span><input id="custom-key" placeholder="e.g. Batch number" maxlength="80"></label><label class="field"><span>Value</span><input id="custom-value" placeholder="Enter a value"></label>`,`<button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-add-custom="${scope}">Add property</button>`);}else actions[action.dataset.action]?.(event);return;}
 const add=event.target.closest('[data-add-custom]');if(add&&canEdit()){const key=$('#custom-key').value.trim(),val=$('#custom-value').value;if(!key||['__proto__','prototype','constructor'].includes(key)){toast('Enter a valid property name');return;}const item=store.diagram.nodes.find(n=>selected.has(n.id))||store.diagram.edges.find(e=>selected.has(e.id));const current=add.dataset.addCustom==='metadata'?store.diagram.metadata:item?.properties.additional;if(Object.hasOwn(current||{},key)){toast('This property already exists');return;}store.commit(d=>{if(add.dataset.addCustom==='metadata')d.metadata[key]=val;else if(item){item.properties.additional||={};item.properties.additional[key]=val;}});$('#modal').close();return;}
 const remove=event.target.closest('[data-remove-property]');if(remove&&canEdit()){store.commit(d=>{const item=d.nodes.find(n=>selected.has(n.id))||d.edges.find(e=>selected.has(e.id));const obj=remove.dataset.customScope==='metadata'?d.metadata:item?.properties.additional;if(obj)delete obj[remove.dataset.removeProperty];});return;}
 const fmt=event.target.closest('[data-export-format]');if(fmt){exportFormat=fmt.dataset.exportFormat;$$('[data-export-format]').forEach(b=>b.classList.toggle('active',b===fmt));$('#scale-field').hidden=['svg','xml'].includes(exportFormat);updateExportDimensions();return;}
 const modeButton=event.target.closest('[data-mode]');if(modeButton){setMode(modeButton.dataset.mode);return;}
 const toolButton=event.target.closest('[data-tool]');if(toolButton){setTool(toolButton.dataset.tool);return;}
 const component=event.target.closest('[data-component]');if(component&&!component.disabled){addComponent(component.dataset.component);return;}
 const focus=event.target.closest('[data-focus]');if(focus){focusElement(focus.dataset.focus);return;}
 if(!event.target.closest('#context-menu'))$('#context-menu').hidden=true;
});
function updateExportDimensions(){const b=bounds(store.diagram),scale=Number($('#export-scale').value);$('#export-dimensions').textContent=exportFormat==='xml'?`${store.project.diagrams.length} flows · ${store.project.diagrams.reduce((n,d)=>n+d.nodes.length,0)} components · Project XML 2.0`:exportFormat==='svg'?'Scalable vector · '+store.diagram.settings.theme+' theme':`${Math.ceil(b.width*scale)} × ${Math.ceil(b.height*scale)} px · ${exportFormat==='png-transparent'?'Transparent background':store.diagram.settings.theme+' theme'}`;}
document.addEventListener('change',event=>{
 const el=event.target;if(el.id==='export-scale'){updateExportDimensions();return;}
 if(el.dataset.custom&&canEdit()){const item=store.diagram.nodes.find(n=>selected.has(n.id))||store.diagram.edges.find(e=>selected.has(e.id));store.commit(d=>{const obj=el.dataset.customScope==='metadata'?d.metadata:(item.properties.additional||={});obj[el.dataset.custom]=el.value;});return;}
 if(!el.dataset.field||!canEdit())return;
 const key=el.dataset.field,scope=el.dataset.scope,value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;
 if(scope==='settings'&&key==='orientation'){orientation(value);return;}
 if(el.type==='number'&&(!Number.isFinite(value)||Math.abs(value)>100000)){toast('Enter a valid number between −100,000 and 100,000');renderInspector();return;}
 if((key==='width'&&value<64)||(key==='height'&&value<48)||(key==='gridSize'&&(value<8||value>80))){toast('Value is outside the supported range');renderInspector();return;}
 const item=store.diagram.nodes.find(n=>selected.has(n.id))||store.diagram.edges.find(e=>selected.has(e.id));
 if(scope==='node'&&key==='type'&&definitions[value].container&&store.diagram.edges.some(e=>e.source===item.id||e.destination===item.id)){toast('Disconnect streams before converting to a container');renderInspector();return;}
 store.commit(d=>{if(scope==='diagram')d[key]=value;else if(scope==='settings')d.settings[key]=value;else if(scope==='node'||scope==='edge')item[key]=value;else if(item)item.properties[key]=value;});
});
