canvas.addEventListener('pointerdown',event=>{
 if(event.button===2)return;$('#context-menu').hidden=true;canvas.focus();const p=world(event),pEl=event.target.closest('[data-port]'),resize=event.target.closest('[data-resize]'),route=event.target.closest('[data-route]'),nEl=event.target.closest('[data-node]'),eEl=event.target.closest('[data-edge]');
 if(space||tool==='pan'||event.button===1){event.preventDefault();gesture={kind:'pan',start:{x:event.clientX,y:event.clientY},camera:{...camera},pointer:event.pointerId};canvas.setPointerCapture(event.pointerId);canvas.style.cursor='grabbing';return;}
 if(pEl&&canEdit()){const target={node:pEl.dataset.node,side:pEl.dataset.port};if(connecting&&finishConnection(target))return;connecting=target;document.body.classList.add('connecting');$('#connection-hint').hidden=false;gesture={kind:'connect',pointer:event.pointerId};canvas.setPointerCapture(event.pointerId);return;}
 if(connecting&&canEdit()){const target=nearestPort(event);if(target&&finishConnection(target))return;}
 if(resize&&canEdit()){const n=store.diagram.nodes.find(n=>n.id===resize.dataset.resize);gesture={kind:'resize',node:n.id,start:p,width:n.width,height:n.height,pointer:event.pointerId};canvas.setPointerCapture(event.pointerId);return;}
 if(route&&canEdit()){gesture={kind:'route',edge:route.dataset.route,start:p,pointer:event.pointerId};canvas.setPointerCapture(event.pointerId);return;}
 if(nEl){const id=nEl.dataset.node;if(event.shiftKey){select(id,true);return;}if(!selected.has(id)||selected.size===1)select(id);if(canEdit()&&tool!=='connect'){const node=store.diagram.nodes.find(n=>n.id===id);let moving=store.diagram.nodes.filter(n=>selected.has(n.id));if(definitions[node.type].container){const contained=store.diagram.nodes.filter(n=>n.id!==id&&n.x>=node.x&&n.y>=node.y&&n.x+n.width<=node.x+node.width&&n.y+n.height<=node.y+node.height);moving=[...new Map([...moving,...contained].map(n=>[n.id,n])).values()];}gesture={kind:'move',start:p,positions:moving.map(n=>({id:n.id,x:n.x,y:n.y})),pointer:event.pointerId};canvas.setPointerCapture(event.pointerId);}return;}
 if(eEl){select(eEl.dataset.edge,event.shiftKey);return;}
 if(!event.shiftKey)select(null);
 if(tool==='connect'){cancelConnect();return;}
 gesture={kind:mode==='view'?'pan':'box',start:mode==='view'?{x:event.clientX,y:event.clientY}:p,camera:{...camera},previous:new Set(selected),pointer:event.pointerId};canvas.setPointerCapture(event.pointerId);
});
canvas.addEventListener('pointermove',event=>{
 const p=world(event);
 if(connecting){const n=store.diagram.nodes.find(n=>n.id===connecting.node);if(n){const a=port(n,connecting.side),target=nearestPort(event),q=target?port(store.diagram.nodes.find(n=>n.id===target.node),target.side):p;overlay.innerHTML=`<path d="${roundedPath([a,{x:(a.x+q.x)/2,y:a.y},{x:(a.x+q.x)/2,y:q.y},q])}" fill="none" stroke="${palettes[store.diagram.settings.theme].accent}" stroke-width="2" stroke-dasharray="5 4"/><circle cx="${q.x}" cy="${q.y}" r="${target?7:4}" fill="${palettes[store.diagram.settings.theme].accent}"/>`;}}
 if(!gesture)return;const g=gesture;
 if(g.kind==='pan'){camera.x=g.camera.x+event.clientX-g.start.x;camera.y=g.camera.y+event.clientY-g.start.y;viewTransform();return;}
 if(g.kind==='box'){const x=Math.min(g.start.x,p.x),y=Math.min(g.start.y,p.y),w=Math.abs(g.start.x-p.x),h=Math.abs(g.start.y-p.y);overlay.innerHTML=`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${palettes[store.diagram.settings.theme].accent}" fill-opacity=".07" stroke="${palettes[store.diagram.settings.theme].accent}" stroke-width="1"/>`;selected.clear();g.previous.forEach(id=>selected.add(id));store.diagram.nodes.filter(n=>n.x>=x&&n.y>=y&&n.x+n.width<=x+w&&n.y+n.height<=y+h).forEach(n=>selected.add(n.id));renderCanvas();return;}
 if(!canEdit()||g.kind==='connect')return;
 if(Math.hypot(p.x-g.start.x,p.y-g.start.y)<2&&!activePreview)return;
 activePreview=clone(store.diagram);
 if(g.kind==='move'){const dx=snap(p.x-g.start.x),dy=snap(p.y-g.start.y);g.positions.forEach(v=>{const n=activePreview.nodes.find(n=>n.id===v.id);n.x=v.x+dx;n.y=v.y+dy;});}
 if(g.kind==='resize'){const n=activePreview.nodes.find(n=>n.id===g.node);n.width=Math.max(100,snap(g.width+p.x-g.start.x));n.height=Math.max(70,snap(g.height+p.y-g.start.y));}
 if(g.kind==='route'){const e=activePreview.edges.find(e=>e.id===g.edge);e.routing='manual';e.routeOffset=snap(['left','right'].includes(e.sourcePort)?p.x:p.y);}
 renderCanvas(activePreview);
});
function endGesture(event,cancel=false){const g=gesture;if(!g)return;if(g.kind==='connect'&&!cancel)finishConnection(nearestPort(event));if(activePreview&&!cancel&&canEdit()){const next=activePreview;activePreview=null;store.commit(d=>{d.nodes=next.nodes;d.edges=next.edges;});}activePreview=null;gesture=null;if(canvas.hasPointerCapture(event.pointerId))canvas.releasePointerCapture(event.pointerId);canvas.style.cursor=tool==='pan'?'grab':tool==='connect'?'crosshair':'default';if(!connecting)overlay.innerHTML='';renderCanvas();renderInspector();updateHeader();}
