window.addEventListener('keydown',event=>{
 const editing=event.target instanceof Element&&event.target.closest('input,textarea,select,[contenteditable=true]');const mod=event.ctrlKey||event.metaKey;
 if(event.key==='Escape'){cancelConnect();$('#context-menu').hidden=true;if(gesture){gesture=null;activePreview=null;renderCanvas();}if(!$('#modal').open&&!editing)select(null);return;}
 if($('#modal').open||editing||event.target.closest?.('#flow-tabs'))return;
 if(event.code==='Space'){event.preventDefault();space=true;canvas.style.cursor='grab';return;}
 if(mod){const k=event.key.toLowerCase();if(['z','y','s','o','c','v','d','a'].includes(k))event.preventDefault();if(k==='z')event.shiftKey?actions.redo():actions.undo();if(k==='y')actions.redo();if(k==='s')actions.save();if(k==='o')actions.open();if(k==='c')copy();if(k==='v')paste();if(k==='d')actions.duplicate();if(k==='a'){selected.clear();store.diagram.nodes.forEach(n=>selected.add(n.id));render();}return;}
 if(['Delete','Backspace'].includes(event.key)){event.preventDefault();deleteSelection();}else if(event.key.toLowerCase()==='f')fit();else if(event.key.toLowerCase()==='v')setTool('select');else if(event.key.toLowerCase()==='h')setTool('pan');else if(event.key.toLowerCase()==='c')setTool('connect');else if(event.key==='/'){event.preventDefault();document.body.classList.remove('library-hidden');$('#component-search').focus();}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)&&canEdit()&&selected.size){event.preventDefault();const step=event.shiftKey?1:store.diagram.settings.snap?store.diagram.settings.gridSize:10;store.commit(d=>{d.nodes.filter(n=>selected.has(n.id)).forEach(n=>{n.x+=(event.key==='ArrowRight'?step:event.key==='ArrowLeft'?-step:0);n.y+=(event.key==='ArrowDown'?step:event.key==='ArrowUp'?-step:0);});});}
});
